"""Report-only: for each `Module:N` / `:N` / `–N` reference in a report line, print the
declaration found at that source line and whether its name is among the line's backticked names.
Never edits anything."""
import re, sys, pathlib

root = pathlib.Path(sys.argv[2])  # formal/Ern/Concurrency
doc = pathlib.Path(sys.argv[1]).read_text().splitlines()
decl = re.compile(r'^\s*(?:private\s+|protected\s+)?(?:theorem|lemma|def|abbrev|structure|inductive|instance|class)\s+([^\s(:{\[]+)')
ref = re.compile(r'`([A-Za-z/]+(?:\.lean)?):(\d+)`|`:(\d+)`|`?–`?(\d+)`')
cache = {}

def src(mod):
    mod = mod.removesuffix('.lean')
    if mod not in cache:
        p = root / (mod + '.lean')
        cache[mod] = p.read_text().splitlines() if p.exists() else None
    return cache[mod]

for i, line in enumerate(doc, 1):
    names = set(re.findall(r'`([^`]+)`', line))
    names = {w for n in names for w in re.split(r'[\s,]+', n)}
    mod = None
    for m in ref.finditer(line):
        if m.group(1):
            mod, n = m.group(1), int(m.group(2))
        elif mod is None:
            print(f'{i}: orphan {m.group(0)}'); continue
        else:
            n = int(m.group(3) or m.group(4))
        lines = src(mod)
        if lines is None:
            print(f'{i}: no module {mod}'); continue
        if n > len(lines):
            print(f'{i}: {mod}:{n} beyond EOF'); continue
        d = decl.match(lines[n - 1])
        got = d.group(1) if d else lines[n - 1].strip()[:50]
        short = got.split('.')[-1]
        ok = d and (got in names or short in names or any(x.endswith(short) for x in names))
        print(f'{i}: {mod}:{n} -> {got} {"OK" if ok else "CHECK"}')

